using System;
using System.IO;
using System.Text;
using UnityEditor;

namespace HYC.Framework.Editor
{
    /// <summary>
    /// 生成代码统一写盘（包内最底层）：
    /// ① 每个产出的 .cs 顶部套「自动生成」壳——IDE 识别的 <c>&lt;auto-generated&gt;</c> 标签 +
    ///    禁手工改声明 + 变更指引，让人（和工具）一眼看出这文件不能手改；
    /// ② 内容未变则不重写、不触发 <see cref="AssetDatabase.ImportAsset(string, ImportAssetOptions)"/>
    ///    （避免无谓的重新导入与编译抖动）。
    /// <para>
    /// 所有代码生成器必须走这里写 .cs，不得直接 <c>File.WriteAllText</c>——
    /// 否则生成文件缺禁改头。壳内<b>不含时间戳/路径等易变信息</b>，否则每次生成内容都不同、
    /// 「未变不重写」会失效。
    /// </para>
    /// </summary>
    public static class GeneratedCodeFile
    {
        /// <summary>
        /// 生成文件头（壳）。四行注释：自动生成标签 + 中英文禁改声明 + 变更指引。
        /// 行尾随平台（与生成内容一致）；刻意不含时间戳等易变信息。
        /// </summary>
        public static readonly string Header = string.Join(Environment.NewLine,
            "// <auto-generated>",
            "// 此文件由 HYC Framework 代码生成器自动生成，请勿手工修改——任何改动都会在下次生成时被覆盖。",
            "// This file is auto-generated by the HYC Framework code generator. DO NOT EDIT.",
            "// 如需变更，请修改生成源（配置模板 / 数据资产）后重新生成。",
            "// </auto-generated>",
            "");

        /// <summary>给生成内容套壳（头在前，原内容整体后移）。</summary>
        public static string WithHeader(string code) => Header + code;

        /// <summary>
        /// 写盘前先比对内容：一致则跳过写入。路径相对工程根（传绝对路径则原样使用）。
        /// 纯比对写盘、不套壳——套壳请走 <see cref="WriteAndImport"/> 或自行 <see cref="WithHeader"/>。
        /// </summary>
        public static bool WriteIfChanged(string relativePath, string content)
        {
            var fullPath = Path.IsPathRooted(relativePath)
                ? relativePath
                : Path.Combine(Directory.GetCurrentDirectory(), relativePath);
            if (File.Exists(fullPath))
            {
                try
                {
                    if (string.Equals(File.ReadAllText(fullPath, Encoding.UTF8), content, StringComparison.Ordinal))
                        return false;
                }
                catch (IOException)
                {
                    // 读不出来（被占用/编码异常）→ 照常写
                }
            }
            File.WriteAllText(fullPath, content, Encoding.UTF8);
            return true;
        }

        /// <summary>套壳 + 写盘 + 按需导入（内容未变则跳过写入与导入）。</summary>
        public static void WriteAndImport(string relativePath, string content)
        {
            if (WriteIfChanged(relativePath, WithHeader(content)))
                AssetDatabase.ImportAsset(relativePath, ImportAssetOptions.ForceUpdate);
        }
    }
}
